import{_ as t,o as a,c as r,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Guest calculation production activation","description":"","frontmatter":{},"headers":[],"relativePath":"operations/guest-calculation-production-activation.md","filePath":"operations/guest-calculation-production-activation.md","lastUpdated":1788532705000}'),i={name:"operations/guest-calculation-production-activation.md"};function d(n,e,c,s,l,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="guest-calculation-production-activation" tabindex="-1">Guest calculation production activation <a class="header-anchor" href="#guest-calculation-production-activation" aria-label="Permalink to &quot;Guest calculation production activation&quot;">​</a></h1><p>Status: <strong>Production backend verified; paired public client activation approved</strong> Assessment timestamp: <code>2026-09-04T15:50:00+05:30</code> (<code>Asia/Kolkata</code>) Release refresh: <code>2026-09-04</code> (<code>Asia/Kolkata</code>) Panchangam pre-activation baseline: <code>99629ada</code> Epic: <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/234" target="_blank" rel="noreferrer">#234</a></p><p>This is the operator runbook and release record for guest birth-profile calculation and Muhurtam election-chart screening. The owner approved the AGPL-compatible public-source path and paired public activation on 2026-09-04 after the exact Production backend passed the bounded probes below. The evidence and rollback checks still apply to every release and rollback step.</p><p>Refresh this record immediately before any Preview, merge, deployment, or activation approval. Reconfirm branch heads, CI/security check URLs, exact Vercel deployment IDs, environment-name inventories, public probes, and restore refs; the values below are a dated assessment, not perpetual release evidence.</p><h2 id="current-state" tabindex="-1">Current state <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current state&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>State</th></tr></thead><tbody><tr><td>Panchangam profile/Muhurtam UI</td><td>The reviewed production build sets both remote client flags to exact <code>true</code>; PR #452 is the paired client activation and requires a manual <code>Deploy Landing Page</code> dispatch because <code>.env.production</code> is outside the workflow&#39;s push paths.</td></tr><tr><td>Astro guest routes</td><td>Production deployment <code>dpl_G49CJ75b1YsLCR872fbaptpEiGPe</code> is Ready at exact public commit <code>4106f097</code>; health, birth, election-chart, and governed place-search probes passed.</td></tr><tr><td>DashaFlow authenticated contracts</td><td>Production deployment <code>dpl_DmZ3sEMEvtCMo7EGpY7zRtEP2ySJ</code> at public commit <code>c84fd856</code> served the authenticated synthetic birth and election-chart derivations through Astro. The browser never receives the sidecar credential.</td></tr><tr><td>Panchangam release posture</td><td>PR #456 merged normally at <code>99629ada</code>; tag <code>v1.14.0</code> publishes the reviewed AGPL/source package and release evidence.</td></tr><tr><td>Licensing</td><td>The relevant repositories are public and the reviewed TCU source/package posture is AGPL-3.0-or-later with direct PySwissEph and Swiss Ephemeris notices.</td></tr><tr><td>Production geocoder/shared controls</td><td>Keyless public Nominatim is active on the shared governed path. A bounded Hyderabad search returned 200. In a 65-attempt <code>/api/guest/</code> probe from one client, 60 were admitted and the subsequent five returned edge 429 without creating an application draft.</td></tr><tr><td>Rollback</td><td>Preserve the exact pre-activation TCU master archive created from <code>99629ada</code> and the existing Pages archive <code>archive/pre-public-activation-2026-09-04-gh-pages-79c907d</code>.</td></tr></tbody></table><h2 id="cleared-activation-evidence" tabindex="-1">Cleared activation evidence <a class="header-anchor" href="#cleared-activation-evidence" aria-label="Permalink to &quot;Cleared activation evidence&quot;">​</a></h2><ul><li>The owner selected and approved the public AGPL-compatible source posture, Production backend, and paired birth/election client activation.</li><li>Astro Production is Ready at exact public source <code>4106f097</code> and immutable deployment <code>dpl_G49CJ75b1YsLCR872fbaptpEiGPe</code>.</li><li>A Hyderabad Production place search returned 200 with the governed Nominatim provider. The WAF probe admitted 60 requests from one client, then the next five returned edge 429 without creating an application draft.</li><li>Synthetic birth derivation returned 200 with Jyeshtha Padam 4, Vrischika and Simha; synthetic election-chart derivation returned 200.</li><li>TCU schema-v1 compatibility was restored by #458 before the versioned release, and #456 passed the full Python 3.10-3.13/security gates before its normal merge.</li><li>The paired client activation is pinned by <code>tests/test_production_activation_flags.py</code>; both exact production flags, the deploy run, the resulting <code>gh-pages</code> tip, and live browser/API probes must be recorded on #452 and epic #234.</li></ul><h2 id="version-record" tabindex="-1">Version record <a class="header-anchor" href="#version-record" aria-label="Permalink to &quot;Version record&quot;">​</a></h2><p>Fill this table without secret values.</p><p>Do not reuse one value for production, candidate, or rollback. Record immutable deployment IDs rather than mutable aliases.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Current Production commit</th><th>Candidate runtime/code commit</th><th>Restore ref</th><th>Preview deployment ID</th><th>Production deployment ID</th><th>CI/security evidence</th></tr></thead><tbody><tr><td>Panchangam</td><td><code>99629ada</code> before client activation</td><td>PR #452, both production client flags exact <code>true</code></td><td>New immutable archive at exact <code>99629ada</code>; existing Pages archive <code>archive/pre-public-activation-2026-09-04-gh-pages-79c907d</code></td><td>Local production build and fixture-backed browser review</td><td>Manual <code>Deploy Landing Page</code> run from exact merged #452 revision</td><td>PR #456: full local suite 1,466 passed/1 skipped, full build/docs passed, and required Python 3.10-3.13, CodeQL, pip-audit and Sonar checks passed; #452 requires the same final-head gates.</td></tr><tr><td>Astro</td><td><code>4106f097</code></td><td>same exact Production source revision</td><td>Repository/archive and Vercel instant rollback retained by the Astro release record</td><td>Earlier protected pair remains recorded in #448</td><td><code>dpl_G49CJ75b1YsLCR872fbaptpEiGPe</code> (Ready)</td><td>Health 200; governed Hyderabad search 200; synthetic birth and election charts 200; WAF admitted 60 requests before five subsequent edge 429 responses.</td></tr><tr><td>DashaFlow</td><td><code>c84fd856</code></td><td>same exact released Production source revision</td><td>Retained by the DashaFlow/Astro release record</td><td>Exact-token protected Preview evidence remains in #448</td><td><code>dpl_DmZ3sEMEvtCMo7EGpY7zRtEP2ySJ</code> (Ready)</td><td>Synthetic birth and election calls passed through the Production gateway with DashaFlow 1.1.0 and disclosed Moshier ephemeris; no browser credential exists.</td></tr></tbody></table><h2 id="environment-names-and-implementation-state" tabindex="-1">Environment names and implementation state <a class="header-anchor" href="#environment-names-and-implementation-state" aria-label="Permalink to &quot;Environment names and implementation state&quot;">​</a></h2><p>These are names only. Never record values here, in issues, or in browser code.</p><table tabindex="0"><thead><tr><th>Owner</th><th>Current implemented name</th><th>Current boundary</th></tr></thead><tbody><tr><td>Panchangam build</td><td><code>VITE_BIRTH_PROFILE_API_ENABLED</code></td><td>exact <code>true</code>; exercise independently</td></tr><tr><td>Panchangam build</td><td><code>VITE_ELECTION_CHART_API_ENABLED</code></td><td>exact <code>true</code>; exercise independently</td></tr><tr><td>Panchangam build</td><td><code>VITE_BIRTH_PROFILE_API_BASE</code></td><td>implemented, but a deployed build accepts only the canonical Production Astro base; it cannot target a hosted Preview today</td></tr><tr><td>Panchangam build</td><td><code>VITE_ELECTION_CHART_API_BASE</code></td><td>same deployed-host restriction; it cannot target a hosted Preview today</td></tr><tr><td>Astro</td><td><code>GUEST_BIRTH_PROFILE_ENABLED</code></td><td>exact <code>true</code>; deployed/ambiguous runtimes otherwise fail closed</td></tr><tr><td>Astro</td><td><code>GUEST_ELECTION_CHART_ENABLED</code></td><td>exact <code>true</code>; deployed/ambiguous runtimes otherwise fail closed</td></tr><tr><td>Astro</td><td><code>DASHAFLOW_SIDECAR_URL</code></td><td>approved HTTPS service only when deployed</td></tr><tr><td>Astro</td><td><code>DASHAFLOW_SIDECAR_TOKEN</code></td><td>server-only credential sent by Astro</td></tr><tr><td>DashaFlow</td><td><code>DASHAFLOW_API_TOKEN</code></td><td>server-only verifier; its value must match Astro&#39;s differently named token</td></tr><tr><td>Astro</td><td><code>GEOCODER_PROVIDER</code></td><td>Fixed to <code>nominatim-public</code> in Production after owner approval. Preview and real local development reject it and use fixtures.</td></tr><tr><td>Astro</td><td><code>GEOCODER_API_KEY</code></td><td>Must be absent for <code>nominatim-public</code>; a key is needed only if a dormant commercial adapter is selected in a later reviewed release.</td></tr><tr><td>Astro</td><td><code>GEOCODER_DAILY_REQUEST_LIMIT</code></td><td>Set a canonical value no greater than <code>1000</code> for public Nominatim. Guest and managed signed-in cache misses share the same Production provider row.</td></tr><tr><td>Astro</td><td><code>AUTH_PROFILE_MANAGED_GEOCODER_ENABLED</code></td><td>Exact <code>true</code> in Production so signed-in and guest calls share one governed path. Preview remains fixture-only.</td></tr><tr><td>Astro</td><td><code>TURSO_DATABASE_URL</code>, <code>TURSO_AUTH_TOKEN</code></td><td>Existing database used for pseudonymous client/user/fleet counters and one non-personal provider-budget/lease row. No place query or result is stored there.</td></tr><tr><td>Astro</td><td><code>RATE_LIMIT_HMAC_SECRET</code></td><td>Existing server-only HMAC secret for pseudonymous client/user/fleet counter keys.</td></tr><tr><td>Astro runtime</td><td><code>VERCEL_ENV</code>, <code>VERCEL</code>, <code>NODE_ENV</code></td><td>implementation classifies only consistent explicit local or deployed markers; missing, unknown, self-hosted-production, or contradictory markers fail closed</td></tr></tbody></table><p>The selected provider contract is live in Astro Production. Public Nominatim is fixed and keyless; no LocationIQ, Geoapify, Upstash, or Redis account is required. It is intentionally unavailable in Preview and real local development, where provider behavior is fixture-tested. Production guest and signed-in place search share one Turso-backed budget and send lease; missing or inconsistent runtime/configuration signals still fail closed.</p><h3 id="place-search-retention-and-quota-contract" tabindex="-1">Place-search retention and quota contract <a class="header-anchor" href="#place-search-retention-and-quota-contract" aria-label="Permalink to &quot;Place-search retention and quota contract&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Boundary</th><th>Permitted data</th><th>Retention / verification gate</th></tr></thead><tbody><tr><td>Panchangam browser request</td><td>Trimmed city/town query only; no profile name, cookie, birth date/time, or chart</td><td>Transient request state; browser network evidence required</td></tr><tr><td>Astro process state</td><td>Ephemeral HMAC client pseudonym; SHA-256 request key; at most five normalized provider rows</td><td>Bounded 256-entry process cache with a 24-hour TTL; no shared result cache</td></tr><tr><td>Turso limiter tables</td><td>Environment-scoped HMAC client/user/fleet keys plus one provider-family hash and integer count/timing fields</td><td>Window/day rollover and bounded cleanup; no raw query, result, IP, user ID, birth detail, coordinate, or credential</td></tr><tr><td>Public Nominatim</td><td>Deliberately submitted city/town query and Astro&#39;s server egress metadata; no profile name, birth date/time, or provider credential</td><td>Provider-controlled under the linked Nominatim and OSMF policies; one bounded Production smoke query only after approval</td></tr><tr><td>Sentry / application analytics</td><td>No request bodies, raw place query, provider URL query/key, birth payload, or chart</td><td>Verify configuration and inspect Preview events before activation</td></tr></tbody></table><p>The geocoder fleet ceiling is 30 calls per minute, shared by guest place search and the activated signed-in migration. The managed signed-in path also applies a ten-call-per-user minute limit. Public Nominatim adds a code-capped 1,000-attempt UTC-day budget and one exclusive 12,500 ms crash-recovery lease; normal completion establishes a fenced 1,100 ms cooldown before the next distributed send. When public Nominatim returns <code>429</code>, a bounded numeric or HTTP-date <code>Retry-After</code> replaces that normal cooldown fleet-wide through the same exact-fence update, up to 24 hours. Missing, malformed, past, or zero-delay guidance becomes 60 seconds. Guest place search applies a durable 50-request allowance of valid managed-provider cache misses per client and anchored 24-hour window. It runs after the five-per-minute guard, validation, cache lookup, and duplicate coalescing and has its own bounded two-second storage deadline. Malformed requests and reusable results do not spend it, though malformed requests may already spend the earlier route capacity, fleet, and minute guards. Fifty is nominally 5% of the configured pool and prevents one client identity from exhausting the provider&#39;s UTC-day allowance. Because the client window is anchored rather than UTC-aligned, a boundary overlap can reach 100 upstream attempts in one UTC day. Warm-process cache hits and coalesced duplicate callers spend no provider slot. These controls implement the public service&#39;s absolute one-request/second application ceiling; they are not a purchased quota or availability guarantee.</p><p>For Turso capacity planning, a successful guest place cache miss uses five admission-path row mutations: the capacity, fleet, minute-client, anchored daily-client, and provider-reservation rows. The conditional exact-fence completion update is accounted separately. Any four-write guest-place estimate predates the anchored daily-client guard and is no longer valid.</p><h2 id="production-evidence-sequence" tabindex="-1">Production evidence sequence <a class="header-anchor" href="#production-evidence-sequence" aria-label="Permalink to &quot;Production evidence sequence&quot;">​</a></h2><p>The protected Astro/DashaFlow pair first passed exact-token contracts against an isolated staging Turso database. The owner then approved and verified the exact Production backend before the paired public client release. Public Nominatim remains intentionally unavailable outside Production; do not weaken CORS, expose a protection credential to browser JavaScript, or point a hosted Preview browser at Production.</p><ol><li>Astro Production deployment <code>dpl_G49CJ75b1YsLCR872fbaptpEiGPe</code> at public source <code>4106f097</code> reported Ready and health returned 200.</li><li>The governed Production Nominatim path returned a bounded Hyderabad result with attribution. The perimeter probe admitted 60 requests from one client; the subsequent five returned edge 429 without an application draft.</li><li>Synthetic Production birth and election requests both returned 200; the birth fixture resolved to Jyeshtha Padam 4, Vrischika and Simha.</li><li>TCU <code>v1.14.0</code> publishes the reviewed source/licence posture from exact pre-activation master <code>99629ada</code>.</li><li>PR #452 sets both client flags together, pins them in a release-contract test, preserves the pre-activation master and Pages refs, and requires a manual landing-page deployment plus live browser verification.</li></ol><h2 id="failure-matrix" tabindex="-1">Failure matrix <a class="header-anchor" href="#failure-matrix" aria-label="Permalink to &quot;Failure matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>Expected behavior</th></tr></thead><tbody><tr><td>Client flag absent/malformed</td><td>No remote call; manual profile entry or conservative unscreened Muhurtam result</td></tr><tr><td>Astro route flag off</td><td>Fixed 503; no geocoder/sidecar call</td></tr><tr><td>Shared Turso limiter missing/unavailable in Preview/Production</td><td>Fixed 503; no expensive calculation/provider call</td></tr><tr><td>Production geocoder configuration missing/unavailable</td><td>Place search 503; no arbitrary or commercial fallback</td></tr><tr><td>Guest client exceeds 50 valid managed-provider place-search misses in its anchored 24-hour window</td><td>Sanitized 429 with durable client-window retry guidance; no provider call</td></tr><tr><td>Public Nominatim returns 429</td><td>Sanitized 429; bounded upstream retry guidance is persisted fleet-wide through exact-fence completion. Missing, malformed, past, or zero-delay guidance becomes 60 seconds; the maximum is 24 hours</td></tr><tr><td>Authenticated migration flag absent/false</td><td>Production preserves its old unbudgeted signed-in Nominatim path; Preview fails closed. Never use this as a Nominatim incident rollback.</td></tr><tr><td>Authenticated migration exact <code>true</code>, provider/limit unavailable</td><td>Signed-in place-changing operation fails closed; no legacy or commercial fallback and no profile mutation</td></tr><tr><td>Sidecar token missing/bad</td><td>Fixed gateway error; no upstream diagnostic or token in response</td></tr><tr><td>Sidecar timeout/transient error</td><td>Up to two bounded attempts within the browser deadline, with one retry only for 502/503/504, then a fixed unavailable result</td></tr><tr><td>Malformed/inconsistent chart</td><td>502/invalid response; never save or score as verified</td></tr><tr><td>Unsupported or ambiguous civil time</td><td>422; offer manual entry</td></tr></tbody></table><h2 id="merge-and-production-sequence" tabindex="-1">Merge and Production sequence <a class="header-anchor" href="#merge-and-production-sequence" aria-label="Permalink to &quot;Merge and Production sequence&quot;">​</a></h2><p>Backend readiness and paired activation have separate evidence, even though the owner approved both public client capabilities in the same release.</p><ol><li>Keep Astro at the exact verified Production revision and keep both routes independently fail-closed when their server configuration is absent.</li><li>Publish and verify TCU <code>v1.14.0</code> from exact merge <code>99629ada</code> before the client activation merge.</li><li>Create an immutable archive at <code>99629ada</code>, retain the existing <code>gh-pages</code> archive at <code>79c907d</code>, then merge #452 normally only after its final-head Python 3.10-3.13 and security checks pass.</li><li>Manually dispatch <code>Deploy Landing Page</code> on the merged #452 master revision; the production environment file is deliberately outside the push path filters.</li><li>Record the resulting workflow run and <code>gh-pages</code> tip, then verify the public page, visible OpenStreetMap attribution, synthetic birth derivation and election-chart screening from a cache-busted browser session.</li></ol><p>Publishing uses the existing manual <code>Deploy Landing Page</code> workflow dispatch because the production environment and documentation files are outside its push path filters. <code>.github/workflows/</code> remains unchanged and frozen.</p><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Record distinct current-Production, candidate, and restore identifiers before each mutation. A mutable branch name, alias, or “previous deployment” label is not sufficient.</p><ul><li><strong>Feature kill:</strong> first set the matching Astro server flag false and redeploy, then publish a Panchangam build with the corresponding <code>VITE_*</code> flag absent or false. During token rollback, keep both routes off until old/new credentials have completed an approved overlap or coordinated cutover.</li><li><strong>Panchangam code:</strong> restore exact pre-activation commit <code>99629ada</code> through immutable branch <code>archive/pre-public-activation-2026-09-04-tcu-master-99629ad</code>. Resolve and record the full commit ID again immediately before release.</li><li><strong>Astro/DashaFlow:</strong> restore the separately recorded immutable deployment IDs and commits. Do not assume a Vercel alias still points to the reviewed build.</li><li><strong>Provider/control failure:</strong> turn both guest server flags off first, but keep <code>AUTH_PROFILE_MANAGED_GEOCODER_ENABLED=true</code> while Production can reach public Nominatim. Turning it off restores the old unbudgeted signed-in path. To stop Nominatim completely, leave that migration flag true and remove the provider selection so signed-in and guest place lookups fail closed together.</li><li><strong>Browser data:</strong> preserve the profile schema and stored records; disabling remote calculation must not make existing profiles unreadable.</li><li><strong>GitHub Pages:</strong> preserve and compare the complete published <code>gh-pages</code> tip and tree, not only <code>index.html</code>. The rollback manifest must include <code>CNAME</code>, all current feeds and per-city Lagna JSON, the Gochara snapshot, the retained Rasi Phalalu tree, built assets, and the site shell. Follow <a href="./gh-pages-retention">GitHub Pages retention and rollback</a>; do not repeat a partial orphan deployment that drops layered artifacts.</li></ul><h2 id="decision-links" tabindex="-1">Decision links <a class="header-anchor" href="#decision-links" aria-label="Permalink to &quot;Decision links&quot;">​</a></h2><ul><li><a href="https://operations.osmfoundation.org/policies/nominatim/" target="_blank" rel="noreferrer">Public Nominatim usage policy</a></li><li><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap copyright and attribution</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/231" target="_blank" rel="noreferrer">Licensing gate #231</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/444" target="_blank" rel="noreferrer">Existing-distribution audit #444</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/445" target="_blank" rel="noreferrer">License-posture implementation #445</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/449" target="_blank" rel="noreferrer">PySwissEph rights or replacement #449</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/233" target="_blank" rel="noreferrer">Geocoder gate #233</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/443" target="_blank" rel="noreferrer">Producer invariants #443</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/446" target="_blank" rel="noreferrer">Managed geocoder/shared controls #446</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/447" target="_blank" rel="noreferrer">Authenticated geocoder migration #447</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/448" target="_blank" rel="noreferrer">Preview certification #448</a></li></ul>',34)])])}const m=t(i,[["render",d]]);export{p as __pageData,m as default};
